{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "There is disagreement about the level of asymptomatic severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2) infection.",
      "reason": "The review describes the current state of knowledge by stating there is disagreement about the level of asymptomatic SARS-CoV-2 infection."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The proportion of people who will remain asymptomatic throughout the course of infection with severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), the cause of coronavirus disease 2019 (COVID-19), is not known.",
      "reason": "The importance/need is explained by identifying that the proportion remaining asymptomatic is not known."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "We found three systematic reviews, which reported similar summary estimates from meta-analysis of studies published up to May [119-121]. In two reviews, authors applied inclusion criteria to reduce the risks of selection bias, with summary estimates of 11% (95% CI 4%-18%, 6 studies) [120] and 15% (95% CI 12%-18%, 9 studies) [121]. Our review includes all these studies, mostly in the categories of aggregated contact or outbreak investigations, with compatible summary estimates (Fig 1).",
      "reason": "When similar systematic reviews exist, the need for the current review is explained by comparing with prior systematic reviews and stating how the current review relates/includes those studies."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No proposed mechanism of action is described because the review is not presented as an intervention-effects review; the retrieved evidence focuses on estimating proportions and transmission related to asymptomatic/presymptomatic infection."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "A logic model for hypothesised relationships between intervention components and outcomes is not considered applicable because the retrieved evidence does not describe a complex intervention or delivery context requiring a logic model."
    }
  ],
  "confidence": 74
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "The objectives of this study were to address three questions: (1) Amongst people who become infected with SARS-CoV-2, what proportion do not experience symptoms at all during their infection? (2) Amongst people with SARS-CoV-2 infection who are asymptomatic when diagnosed, what proportion will develop symptoms later? (3) What proportion of SARS-CoV-2 transmission is accounted for by people who are either asymptomatic throughout infection or presymptomatic?",
      "reason": "The review objectives/questions are explicitly stated as three clear questions."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "We conducted a living systematic review and metaanalysis to address three questions: (1) Amongst people who become infected with SARSCoV-2, what proportion does not experience symptoms at all during their infection? (2) Amongst people with SARS-CoV-2 infection who are asymptomatic when diagnosed, what proportion will develop symptoms later? (3) What proportion of SARS-CoV-2 transmission is accounted for by people who are either asymptomatic throughout infection or presymptomatic?",
      "reason": "The stated objectives are proportion/transmission questions rather than planned intervention comparisons, so PICO (or an appropriate variant for intervention effects) is not applicable."
    }
  ],
  "confidence": 74
}

